#!/bin/sh\nset -e\n\nQUOTES_FILE="/app/quotes.txt"\n\nif [ ! -f "$QUOTES_FILE" ]; then\n  echo "No quotes available."\n  exit 1\nfi\n\n# If QUOTE_INDEX is set, use deterministic selection (for tests)\nif [ -n "$QUOTE_INDEX" ]; then\n  # Ensure the index is a positive integer\n  if echo "$QUOTE_INDEX" | grep -Eq '^[0-9]+$'; then\n    sed -n "${QUOTE_INDEX}p" "$QUOTES_FILE"\n    exit 0\n  else\n    echo "Invalid QUOTE_INDEX: $QUOTE_INDEX"\n    exit 1\n  fi\nfi\n\n# Default: pick a random line\nshuf -n 1 "$QUOTES_FILE"
